insert into public.shoe_products (slug, name, name_ko, brand_id, category, shoe_type, price, compare_at_price, description, story, materials, colorway, image_url, image_alt, sizes, is_new, is_bestseller, stock, sort_order) values
('nike-free-run-crimson','Free Run Flyknit','프리 런 플라이니트 크림슨',(select id from public.shoe_brands where slug = 'nike'),'sports','running',129000,159000,'맨발에 가까운 착화감을 목표로 만든 경량 러닝화입니다. 발등 전체를 감싸는 플라이니트가 발 모양대로 늘어나 조임 없이 고정됩니다.','짧은 거리를 빠르게 달리거나 러닝 후 회복 조깅을 할 때 진가를 발휘합니다. 접어서 가방에 넣을 수 있을 만큼 유연해 출장용으로도 좋습니다.','플라이니트 어퍼, 폼 미드솔','크림슨 레드 / 화이트','https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=900&h=1125&q=80','크림슨 레드 플라이니트 나이키 러닝화 측면','{230,235,240,245,250,255,260,265,270,275,280,285}',false,true,24,1),
('nike-air-force-1-tan','Air Force 1 07 LV8','에어포스 1 LV8 탄',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',139000,null,'1982년 농구화로 태어난 에어포스 1의 스웨이드 버전입니다. 가을·겨울 옷차림에 잘 붙는 따뜻한 탄 컬러로 나왔습니다.','흰색 에어포스가 이미 있다면 다음은 이 색입니다. 데님·코듀로이·베이지 치노 어디에 신어도 톤이 맞습니다.','스웨이드·누벅 어퍼, 에어솔 유닛','휘트 탄 / 검','https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=900&h=1125&q=80','휘트 탄 스웨이드 나이키 에어포스 1 스니커즈','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,30,2),
('nike-af1-shadow-pastel','Air Force 1 Shadow','에어포스 1 섀도우 파스텔',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',159000,null,'스우시와 미드솔을 겹쳐 쌓아 볼륨을 키운 여성용 에어포스입니다. 파스텔 톤이 층층이 들어가 각도마다 색이 다르게 보입니다.','굽이 두꺼워 키가 2cm 정도 커 보입니다. 원피스나 와이드 팬츠처럼 실루엣이 큰 옷과 균형이 잘 맞습니다.','레더 어퍼, 더블 스우시','파스텔 멀티 / 화이트','https://images.unsplash.com/photo-1595950653106-6c9ebd614d3a?auto=format&fit=crop&w=900&h=1125&q=80','파스텔 컬러 나이키 에어포스 1 섀도우 스니커즈','{225,230,235,240,245,250,255,260}',true,false,18,3),
('nike-air-max-sunset','Air Max SC','에어맥스 SC 선셋',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',119000,null,'뒤꿈치의 에어 유닛이 밖에서 보이는 클래식한 구성입니다. 화이트 베이스에 오렌지 그라데이션이 들어가 가벼운 인상을 줍니다.','에어맥스 계열 중 가격 부담이 가장 적은 축입니다. 첫 에어맥스로 고르기 좋습니다.','레더·메시 어퍼, 비저블 에어','화이트 / 선셋 오렌지','https://images.unsplash.com/photo-1600185365483-26d7a4cc7519?auto=format&fit=crop&w=900&h=1125&q=80','화이트와 선셋 오렌지 나이키 에어맥스 스니커즈','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,26,4),
('nike-superrep-volt','SuperRep Go 3','슈퍼렙 고 3 볼트',(select id from public.shoe_brands where slug = 'nike'),'sports','running',149000,null,'실내 트레이닝 전용으로 설계했습니다. 바닥이 넓고 평평해서 스쿼트나 런지처럼 좌우로 흔들리는 동작에서 발이 밀리지 않습니다.','러닝화로 웨이트를 하면 뒤꿈치가 푹 꺼져 자세가 무너집니다. 헬스장에 다닌다면 이런 신발이 따로 하나 있어야 합니다.','통기성 메시, 와이드 아웃솔','볼트 그린 / 블랙','https://images.unsplash.com/photo-1606107557195-0e29a4b5b4aa?auto=format&fit=crop&w=900&h=1125&q=80','볼트 그린 나이키 슈퍼렙 트레이닝화','{230,235,240,245,250,255,260,265,270,275,280,285}',true,false,20,5),
('nike-air-max-90','Air Max 90','에어맥스 90',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',179000,null,'1990년에 나온 원형을 거의 그대로 유지한 모델입니다. 패널마다 소재와 색을 나눠 쓴 구성이 지금 봐도 촌스럽지 않습니다.','30년 넘게 팔리는 데는 이유가 있습니다. 유행을 타지 않아 오래 신을 수 있는 몇 안 되는 스니커입니다.','레더·메시 패널, 비저블 에어','화이트 / 오렌지 / 로열 블루','https://images.unsplash.com/photo-1514989940723-e8e51635b782?auto=format&fit=crop&w=900&h=1125&q=80','오렌지와 블루 배색의 나이키 에어맥스 90 착용 컷','{230,235,240,245,250,255,260,265,270,275,280,285}',false,true,22,6),
('nike-pegasus-shield','Pegasus Shield','페가수스 쉴드 블랙',(select id from public.shoe_brands where slug = 'nike'),'sports','running',159000,null,'비 오는 날 달리기 위한 러닝화입니다. 어퍼에 발수 처리를 하고 아웃솔 패턴을 젖은 노면에 맞춰 바꿨습니다.','장마철에 러닝을 쉬지 않으려면 이 신발이 필요합니다. 다만 완전 방수는 아니라 폭우에는 물이 들어옵니다.','발수 코팅 어퍼, 리액트 폼','블랙 / 다크 그레이','https://images.unsplash.com/photo-1491553895911-0055eca6402d?auto=format&fit=crop&w=900&h=1125&q=80','블랙 컬러 나이키 러닝화','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,16,7),
('jordan-1-high-royal','Air Jordan 1 Retro High OG','에어 조던 1 레트로 하이 OG 로얄',(select id from public.shoe_brands where slug = 'jordan'),'sports','sneakers',289000,null,'1985년 오리지널 배색을 되살린 모델입니다. 발목을 덮는 하이컷과 두툼한 가죽이 특유의 무게감을 만듭니다.','농구화로 시작해 지금은 문화가 된 신발입니다. 처음엔 가죽이 뻣뻣하지만 2주쯤 지나면 발에 맞게 접힙니다.','풀그레인 레더, 에어솔','블랙 / 로열 블루','https://images.unsplash.com/photo-1603787081207-362bcef7c144?auto=format&fit=crop&w=900&h=1125&q=80','블랙과 로열 블루 배색의 에어 조던 1 하이탑','{230,235,240,245,250,255,260,265,270,275,280,285}',false,true,12,8),
('jordan-1-unc','Air Jordan 1 Retro High University Blue','에어 조던 1 레트로 하이 UNC',(select id from public.shoe_brands where slug = 'jordan'),'sports','sneakers',319000,null,'노스캐롤라이나 대학 팀 컬러에서 가져온 하늘색 배색입니다. 흰 바탕에 파랑이 크게 들어가 여름에 특히 잘 어울립니다.','조던 1 배색 중에서도 인기가 높은 편이라 사이즈가 빨리 빠집니다.','레더 어퍼, 러버 아웃솔','유니버시티 블루 / 화이트','https://images.unsplash.com/photo-1588099768531-a72d4a198538?auto=format&fit=crop&w=900&h=1125&q=80','유니버시티 블루 에어 조던 1 착용 컷','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,9,9),
('jordan-1-bred','Air Jordan 1 High OG Bred','에어 조던 1 하이 OG 브레드',(select id from public.shoe_brands where slug = 'jordan'),'sports','sneakers',299000,null,'검정과 빨강만 쓴 가장 상징적인 배색입니다. 리그가 착용을 금지했다는 일화로 더 유명해졌습니다.','무채색 옷이 많은 옷장이라면 이 한 켤레가 포인트를 전부 담당합니다.','풀그레인 레더','블랙 / 바시티 레드','https://images.unsplash.com/photo-1552346154-21d32810aba3?auto=format&fit=crop&w=900&h=1125&q=80','블랙과 레드 배색 에어 조던 1 하이탑 한 켤레','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,11,10),
('jordan-1-shattered-backboard','Air Jordan 1 Shattered Backboard','에어 조던 1 슈터드 백보드',(select id from public.shoe_brands where slug = 'jordan'),'sports','sneakers',349000,null,'주황과 검정이 절반씩 나뉜 배색입니다. 1985년 이탈리아 시범경기에서 백보드를 깨뜨렸던 경기의 유니폼 색을 옮겨왔습니다.','발목에 오렌지가 크게 들어가 크롭 팬츠나 롤업 데님처럼 발목이 보이는 바지와 함께 신으면 가장 예쁩니다.','레더 어퍼, 스웨이드 힐탭','블랙 / 스타피시 오렌지','https://images.unsplash.com/photo-1556906781-9a412961c28c?auto=format&fit=crop&w=900&h=1125&q=80','오렌지와 블랙 배색 에어 조던 1 착용 컷','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,8,11),
('jordan-1-chicago','Air Jordan 1 High OG Chicago','에어 조던 1 하이 OG 시카고',(select id from public.shoe_brands where slug = 'jordan'),'sports','sneakers',399000,null,'조던 1을 대표하는 배색입니다. 흰 가죽에 빨강과 검정을 나눠 넣은 구성으로, 모든 복각의 기준이 되는 모델입니다.','스니커를 한 켤레만 소장한다면 많은 사람이 이걸 고릅니다. 흰 가죽은 생각보다 때가 잘 타니 방수 스프레이를 권합니다.','프리미엄 레더','화이트 / 바시티 레드 / 블랙','https://images.unsplash.com/photo-1597045566677-8cf032ed6634?auto=format&fit=crop&w=900&h=1125&q=80','화이트 레드 블랙 배색의 에어 조던 1 시카고','{230,235,240,245,250,255,260,265,270,275,280,285}',false,true,6,12),
('nike-blazer-mid-77','Blazer Mid 77 Vintage','블레이저 미드 77 빈티지',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',139000,null,'1977년 농구화를 복각하면서 미드솔에 일부러 누런 빛을 넣었습니다. 새 신발인데도 오래 신은 것 같은 분위기가 납니다.','조던 1보다 가볍고 발볼이 편합니다. 하이탑이 부담스러운 분께 권합니다.','레더 어퍼, 빈티지 가공 미드솔','크림 / 오렌지','https://images.unsplash.com/photo-1584735175315-9d5df23860e6?auto=format&fit=crop&w=900&h=1125&q=80','크림과 오렌지 배색의 나이키 블레이저 미드 하이탑','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,19,13),
('nike-af1-mid-cream','Air Force 1 Mid','에어포스 1 미드 크림',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',149000,null,'발목 스트랩이 달린 미드컷입니다. 로우보다 발목을 잡아줘 착화감이 안정적입니다.','스트랩은 풀어서 늘어뜨려도 되고 채워도 됩니다. 채우면 단정하고, 풀면 느슨한 인상이 납니다.','레더 어퍼, 스트랩 디테일','크림 / 새들 브라운','https://images.unsplash.com/photo-1512374382149-233c42b6a83b?auto=format&fit=crop&w=900&h=1125&q=80','크림 컬러 나이키 에어포스 1 미드','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,15,14),
('nike-air-max-pink-blast','Air Max Pink Blast','에어맥스 핑크 블라스트',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',189000,null,'흰 바탕에 형광에 가까운 핑크를 크게 넣었습니다. 뒤꿈치 에어 유닛까지 색이 이어져 옆에서 봤을 때 선이 살아납니다.','무채색 위주 옷차림에 색 하나만 넣고 싶을 때 좋습니다.','메시·레더 혼합, 풀렝스 에어','화이트 / 핑크 블라스트 / 퍼플','https://images.unsplash.com/photo-1511556532299-8f662fc26c06?auto=format&fit=crop&w=900&h=1125&q=80','화이트와 핑크 배색의 나이키 에어맥스','{225,230,235,240,245,250,255,260,265}',true,false,14,15),
('nike-kyrie-infinity','Kyrie Infinity','카이리 인피니티',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',179000,null,'방향 전환이 잦은 가드 포지션을 위해 만든 농구화입니다. 앞꿈치 아웃솔을 곡선으로 깎아 급정지와 회전이 부드럽습니다.','실내 코트용입니다. 아스팔트에서 신으면 아웃솔이 금방 닳습니다.','합성 어퍼, 멀티 트랙션 아웃솔','블랙 / 화이트','https://images.unsplash.com/photo-1605348532760-6753d2c43329?auto=format&fit=crop&w=900&h=1125&q=80','블랙 컬러 나이키 카이리 농구화','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,13,16),
('nike-af1-white','Air Force 1 07','에어포스 1 화이트',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',139000,null,'설명이 필요 없는 흰 스니커의 기준입니다. 전부 흰색이라 어떤 옷에도 붙고, 더러워지면 눈에 띄지만 닦기도 쉽습니다.','슬랙스에 신으면 캐주얼한 오피스룩이 되고, 반바지에 신으면 여름 데일리가 됩니다. 한 켤레로 계절 전체를 버팁니다.','풀그레인 레더, 에어솔 유닛','트리플 화이트','https://images.unsplash.com/photo-1600269452121-4f2416e55c28?auto=format&fit=crop&w=900&h=1125&q=80','올 화이트 나이키 에어포스 1 로우','{230,235,240,245,250,255,260,265,270,275,280,285}',false,true,40,17),
('nike-af1-black','Air Force 1 07 Black','에어포스 1 블랙',(select id from public.shoe_brands where slug = 'nike'),'sports','sneakers',139000,null,'흰색만큼 팔리는 검정 버전입니다. 때가 덜 타서 비 오는 날이나 출퇴근용으로 실용적입니다.','검정 슬랙스와 함께라면 가장 무난하게 정돈된 인상을 줍니다.','풀그레인 레더, 에어솔 유닛','트리플 블랙','https://images.unsplash.com/photo-1570464197285-9949814674a7?auto=format&fit=crop&w=900&h=1125&q=80','올 블랙 나이키 에어포스 1 로우','{230,235,240,245,250,255,260,265,270,275,280,285}',false,false,35,18),
